import{_ as o,C as r,o as t,c as l,j as a,a as s,b as d,w as i,E as c,a2 as h,a3 as g}from"./chunks/framework.pb1iZPmZ.js";const b=JSON.parse('{"title":"14.6 System Design: Multi-Tier Caching","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.6-caching.md","filePath":"system-design/14.6-caching.md"}'),u={name:"system-design/14.6-caching.md"};function p(f,e,m,y,x,w){const n=r("Mermaid");return t(),l("div",null,[e[1]||(e[1]=a("h1",{id:"_14-6-system-design-multi-tier-caching",tabindex:"-1"},[s("14.6 System Design: Multi-Tier Caching "),a("a",{class:"header-anchor",href:"#_14-6-system-design-multi-tier-caching","aria-label":'Permalink to "14.6 System Design: Multi-Tier Caching"'},"​")],-1)),(t(),d(h,null,{default:i(()=>[c(n,{id:"mermaid-3",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20Client%5BBrowser%5D%20--%3E%7C1.%20Browser%20Cache%20(Static%20Assets)%7C%20CDN%5B2.%20Edge%20CDN%20(Cloudflare)%5D%0A%20%20%20%20CDN%20--%3E%7C3.%20Cache%20Miss%7C%20App%5BNode.js%20Express%20App%5D%0A%20%20%20%20App%20%3C--%3E%7C4.%20Redis%20Cache%20(Session%20%26%20User%20Object%20Cache-Aside)%7C%20Redis%5B(%22Redis%20Cluster%22)%5D%0A%20%20%20%20App%20--%3E%7C5.%20DB%20Read%20on%20Cache%20Miss%7C%20DB%5B(%22MongoDB%20Primary%22)%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=g('<hr><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>Caching is the architectural technique of storing frequently requested, high-cost data in high-speed, temporary storage (typically RAM or edge servers) so that future requests can be served in sub-milliseconds without recalculating or querying the primary database.</p><hr><h2 id="_2-whether-and-how-this-project-uses-it" tabindex="-1">2. Whether and How THIS Project Uses It <a class="header-anchor" href="#_2-whether-and-how-this-project-uses-it" aria-label="Permalink to &quot;2. Whether and How THIS Project Uses It&quot;">​</a></h2><p>In the current codebase, caching is <strong>Partially Used</strong>:</p><ul><li><strong>Static Assets</strong>: Browser caching is leveraged by Express&#39;s <code>express.static</code> module for <code>public/</code> files.</li><li><strong>Session Caching</strong>: Not explicitly isolated in RAM; <code>connect-mongo</code> queries MongoDB disk directly for session data on every authenticated request.</li><li><strong>Application Data</strong>: No Redis cache is currently deployed.</li></ul><hr><h2 id="_3-caching-strategies-comparison-table" tabindex="-1">3. Caching Strategies &amp; Comparison Table <a class="header-anchor" href="#_3-caching-strategies-comparison-table" aria-label="Permalink to &quot;3. Caching Strategies &amp; Comparison Table&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Cache Strategy</th><th style="text-align:left;">How It Works</th><th style="text-align:left;">Consistency Risk</th><th style="text-align:left;">Read Latency</th><th style="text-align:left;">Write Latency</th><th style="text-align:left;">Fit for This Auth Portal</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Cache-Aside (Lazy Loading)</strong></td><td style="text-align:left;">App queries cache; on miss, reads DB and populates cache</td><td style="text-align:left;">Low (Invalidate on write)</td><td style="text-align:left;">Sub-millisecond on hit</td><td style="text-align:left;">Standard DB write</td><td style="text-align:left;"><strong>Optimal for user profile hydration</strong></td></tr><tr><td style="text-align:left;"><strong>Read-Through</strong></td><td style="text-align:left;">App treats cache as primary; cache handles DB read</td><td style="text-align:left;">Low</td><td style="text-align:left;">Fast</td><td style="text-align:left;">Standard</td><td style="text-align:left;">Complex cache wrapper setup</td></tr><tr><td style="text-align:left;"><strong>Write-Through</strong></td><td style="text-align:left;">App writes to cache, which synchronously writes to DB</td><td style="text-align:left;">Zero (Always consistent)</td><td style="text-align:left;">Fast</td><td style="text-align:left;">Higher (Two synchronous writes)</td><td style="text-align:left;">Good for mission-critical session updates</td></tr><tr><td style="text-align:left;"><strong>Write-Behind (Write-Back)</strong></td><td style="text-align:left;">App writes to cache; cache batches async writes to DB</td><td style="text-align:left;">High (Data loss on crash)</td><td style="text-align:left;">Fastest</td><td style="text-align:left;">Fastest</td><td style="text-align:left;">Dangerous for clinical authentication records</td></tr></tbody></table><hr><h2 id="_4-cache-invalidation-thundering-herd-defense" tabindex="-1">4. Cache Invalidation &amp; Thundering Herd Defense <a class="header-anchor" href="#_4-cache-invalidation-thundering-herd-defense" aria-label="Permalink to &quot;4. Cache Invalidation &amp; Thundering Herd Defense&quot;">​</a></h2><ol><li><strong>Invalidation Strategy</strong>: <ul><li>When an employee updates their profile: write to MongoDB, then immediately execute <code>redis.del(&#39;user:&#39; + userId)</code> to force a fresh read on the next request.</li><li>When an employee logs out: execute <code>redis.del(&#39;session:&#39; + sessionId)</code> simultaneously with the MongoDB deletion.</li></ul></li><li><strong>Cache Stampede (Thundering Herd) Defense</strong>: <ul><li>If 1,000 clinicians access the system simultaneously during morning shift change when the cache expires, all 1,000 requests could hit MongoDB at once.</li><li><strong>Remediation</strong>: Use <strong>Mutex Locking</strong> (e.g. <code>redlock</code> or a short 5-second distributed lock) so only one request queries MongoDB while the remaining 999 wait for the cache to be repopulated.</li></ul></li></ol><hr><h2 id="_5-what-breaks-first-at-scale" tabindex="-1">5. What Breaks First at Scale <a class="header-anchor" href="#_5-what-breaks-first-at-scale" aria-label="Permalink to &quot;5. What Breaks First at Scale&quot;">​</a></h2><ul><li><strong>10x Load</strong>: MongoDB handles session reads without caching.</li><li><strong>100x Load</strong>: MongoDB read IOPS spike due to duplicate queries across <code>sessions</code> and <code>employees</code>.</li><li><strong>1000x Load</strong>: Database connection pool exhaustion and disk saturation.</li></ul><hr><h2 id="_6-senior-engineering-improvements" tabindex="-1">6. Senior Engineering Improvements <a class="header-anchor" href="#_6-senior-engineering-improvements" aria-label="Permalink to &quot;6. Senior Engineering Improvements&quot;">​</a></h2><p>Introduce a <strong>Redis Cache Cluster</strong> between Express and MongoDB:</p><ol><li>Configure <code>connect-redis</code> as the session store adapter.</li><li>Cache hydrated <code>res.locals.user</code> objects in Redis with a 15-minute TTL.</li><li>Serve <code>login.html</code> and static font files through Cloudflare CDN with a 30-day cache header.</li></ol><hr><h2 id="_7-30-second-spoken-answer" tabindex="-1">7. 30-Second Spoken Answer <a class="header-anchor" href="#_7-30-second-spoken-answer" aria-label="Permalink to &quot;7. 30-Second Spoken Answer&quot;">​</a></h2><blockquote><p>&quot;Right now, every authenticated request queries MongoDB to validate the session and hydrate the user profile. To scale this, I would implement a Cache-Aside pattern using Redis. The server first checks Redis for the session and user profile in under one millisecond. If missed, it queries MongoDB, populates Redis, and invalidates the cache key immediately whenever the user updates their profile or logs out.&quot;</p></blockquote>',23))])}const D=o(u,[["render",p]]);export{b as __pageData,D as default};
